def _install_guards() -> None:
    op.execute("""
        CREATE FUNCTION public.cosmas_guard_vp_clarification()
        RETURNS trigger LANGUAGE plpgsql
        SET search_path = pg_catalog, public AS $$
        DECLARE
          root record;
          proposal record;
          credential record;
          source record;
          correction record;
          scope_id uuid;
          latest_schedule uuid;
          current_source uuid;
          response_count integer;
          event_count integer;
          latest_sequence integer;
          event_at timestamptz;
        BEGIN
          IF TG_OP = 'UPDATE' THEN
            RAISE EXCEPTION 'Visit Prep clarification evidence is immutable'
              USING ERRCODE = '55000';
          END IF;
          IF TG_OP = 'DELETE' THEN
            PERFORM 1 FROM public.visit_prep WHERE id = OLD.visit_prep_id;
            IF FOUND THEN
              RAISE EXCEPTION 'Visit Prep clarification requires aggregate cleanup'
                USING ERRCODE = '55000';
            END IF;
            RETURN OLD;
          END IF;
          scope_id := NEW.visit_prep_id;
          SELECT * INTO root FROM public.visit_prep
           WHERE id = scope_id FOR UPDATE;
          IF NOT FOUND THEN
            RAISE EXCEPTION 'Visit Prep clarification root does not exist'
              USING ERRCODE = '23503';
          END IF;
          SELECT * INTO credential FROM public.visit_prep_credential_generation
           WHERE visit_prep_id = scope_id
             AND owner_practice_member_id = root.owner_practice_member_id
           ORDER BY generation DESC LIMIT 1 FOR UPDATE;
          SELECT id INTO latest_schedule FROM public.visit_prep_schedule_generation
           WHERE visit_prep_id = scope_id
           ORDER BY generation DESC LIMIT 1;
          event_at := clock_timestamp();
          IF root.lifecycle_state NOT IN ('in_progress', 'completed')
             OR root.confirmed_at IS NULL OR root.confirmed_at > event_at
             OR root.started_at IS NULL OR root.started_at > event_at
             OR root.revoked_at IS NOT NULL
             OR credential.generation IS NULL
             OR credential.revoked_at IS NOT NULL
             OR credential.issued_at > event_at
             OR credential.expires_at <= event_at
             OR latest_schedule IS NULL
             OR credential.schedule_generation_id <> latest_schedule THEN
            RAISE EXCEPTION 'Visit Prep clarification requires active current authority'
              USING ERRCODE = '55000';
          END IF;
          SELECT COUNT(*) INTO response_count FROM public.visit_prep_question_response
           WHERE visit_prep_id = scope_id;
          SELECT COUNT(*), COALESCE(MAX(event_sequence), 0)
            INTO event_count, latest_sequence FROM public.visit_prep_contribution_event
           WHERE visit_prep_id = scope_id;
          IF TG_TABLE_NAME = 'visit_prep_clarification_proposal' THEN
            IF NEW.owner_practice_member_id <> root.owner_practice_member_id
               OR NEW.question_set_version_id <> root.question_set_version_id
               OR NEW.actor_role IS DISTINCT FROM root.confirmed_by_role
               OR NEW.credential_generation <> credential.generation THEN
              RAISE EXCEPTION 'Visit Prep clarification lineage does not match'
                USING ERRCODE = '23503';
            END IF;
            IF NEW.basis_response_count <> response_count
               OR NEW.basis_event_sequence <> latest_sequence
               OR event_count <> latest_sequence THEN
              RAISE EXCEPTION 'Visit Prep clarification basis is not current'
                USING ERRCODE = '55000';
            END IF;
            PERFORM 1 FROM public.visit_prep_question
             WHERE id = NEW.question_id
               AND question_set_version_id = root.question_set_version_id;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'Visit Prep clarification question lineage does not exist'
                USING ERRCODE = '23503';
            END IF;
            SELECT e.id INTO current_source
              FROM public.visit_prep_contribution_event e
              LEFT JOIN public.visit_prep_question_response r ON r.id = e.response_id
             WHERE e.visit_prep_id = scope_id
               AND (r.question_id = NEW.question_id OR e.question_id = NEW.question_id)
               AND e.event_kind IN ('correction', 'topic_answer')
             ORDER BY e.event_sequence DESC LIMIT 1;
            IF current_source IS NOT NULL THEN
              SELECT * INTO source FROM public.visit_prep_contribution_event
               WHERE id = current_source;
              IF NEW.source_contribution_id IS DISTINCT FROM current_source
                 OR NEW.source_response_id IS NOT NULL
                 OR source.response_kind <> 'answered' THEN
                RAISE EXCEPTION 'Visit Prep clarification source is not current answered topic'
                  USING ERRCODE = '55000';
              END IF;
            ELSE
              SELECT * INTO source FROM public.visit_prep_question_response
               WHERE visit_prep_id = scope_id AND question_id = NEW.question_id;
              IF source.id IS NULL
                 OR NEW.source_response_id IS DISTINCT FROM source.id
                 OR NEW.source_contribution_id IS NOT NULL
                 OR source.response_kind <> 'answered' THEN
                RAISE EXCEPTION 'Visit Prep clarification source is not current answered topic'
                  USING ERRCODE = '55000';
              END IF;
            END IF;
          ELSE
            SELECT * INTO proposal FROM public.visit_prep_clarification_proposal
             WHERE id = NEW.proposal_id AND visit_prep_id = scope_id;
            IF NOT FOUND THEN
              RAISE EXCEPTION 'Visit Prep clarification proposal lineage does not exist'
                USING ERRCODE = '23503';
            END IF;
            IF proposal.credential_generation <> credential.generation
               OR proposal.actor_role IS DISTINCT FROM root.confirmed_by_role
               OR proposal.basis_response_count <> response_count
               OR event_count <> latest_sequence THEN
              RAISE EXCEPTION 'Visit Prep clarification proposal is stale'
                USING ERRCODE = '55000';
            END IF;
            IF NEW.action IN ('confirm', 'edit') THEN
              SELECT * INTO correction FROM public.visit_prep_contribution_event
               WHERE id = NEW.correction_id AND visit_prep_id = scope_id;
              IF NOT FOUND OR correction.event_kind <> 'correction'
                 OR correction.actor_role <> proposal.actor_role
                 OR correction.credential_generation <> proposal.credential_generation
                 OR correction.basis_response_count <> proposal.basis_response_count
                 OR correction.basis_event_sequence <> proposal.basis_event_sequence
                 OR correction.event_sequence <> latest_sequence
                 OR latest_sequence <> proposal.basis_event_sequence + 1
                 OR correction.response_kind <> 'answered'
                 OR correction.recorded_at < proposal.recorded_at THEN
                RAISE EXCEPTION 'Visit Prep clarification correction is not the exact next event'
                  USING ERRCODE = '55000';
              END IF;
              PERFORM 1 FROM public.visit_prep_question_response
               WHERE id = correction.response_id AND visit_prep_id = scope_id
                 AND question_id = proposal.question_id;
              IF NOT FOUND THEN
                RAISE EXCEPTION 'Visit Prep clarification correction targets another topic'
                  USING ERRCODE = '23503';
              END IF;
              -- Choice supplemental words need a separate source contract.
              PERFORM 1 FROM public.visit_prep_question
               WHERE id = proposal.question_id AND kind IN ('story', 'list');
              IF NOT FOUND THEN
                RAISE EXCEPTION 'Visit Prep clarification choice supplementation is unavailable'
                  USING ERRCODE = '55000';
              END IF;
            ELSIF NEW.action IN ('keep_original', 'dismiss') THEN
              IF NEW.correction_id IS NOT NULL
                 OR latest_sequence <> proposal.basis_event_sequence THEN
                RAISE EXCEPTION 'Visit Prep clarification proposal is stale'
                  USING ERRCODE = '55000';
              END IF;
            END IF;
          END IF;
          NEW.created_at := event_at;
          NEW.updated_at := event_at;
          NEW.recorded_at := event_at;
          RETURN NEW;
        END;
        $$
    """)
    op.execute("""
        CREATE FUNCTION public.cosmas_reject_vp_clarification_truncate()
        RETURNS trigger LANGUAGE plpgsql
        SET search_path = pg_catalog, public AS $$
        BEGIN
          RAISE EXCEPTION 'Visit Prep clarification evidence cannot be truncated'
            USING ERRCODE = '55000';
        END;
        $$
    """)
    for table in ('visit_prep_clarification_proposal', 'visit_prep_clarification_decision'):
        op.execute(f"""
            CREATE TRIGGER {table}_guard_mutation
            BEFORE INSERT OR UPDATE OR DELETE ON public.{table}
            FOR EACH ROW EXECUTE FUNCTION public.cosmas_guard_vp_clarification()
        """)
        op.execute(f"""
            CREATE TRIGGER {table}_guard_truncate
            BEFORE TRUNCATE ON public.{table}
            FOR EACH STATEMENT EXECUTE FUNCTION public.cosmas_reject_vp_clarification_truncate()
        """)


